"""The ``stockroom`` command."""

import csv
import io
import json
import os
import sys
from typing import Dict, List, Optional

from . import orders as orders_mod
from . import shelves
from .parsing import (
    SPACES,
    WHOLE_RE,
    Movement,
    ParseError,
    first_below_zero,
    parse_catalog,
    parse_date,
    parse_movements,
    parse_order_id,
    parse_orders,
    parse_sku,
)
from .pricing import Quote, fmt, price_order

USAGE = """usage: stockroom [--dir DIR] COMMAND ...
commands:
  stock [--json]
  low [--json]
  history SKU [--json]
  receive DATE SKU QUANTITY [NOTE]
  ship DATE SKU QUANTITY [NOTE]
  quote ORDER [--json]
  fulfil ORDER DATE
  invoice ORDER [--json]
  report [--format text|csv|json]
"""

CATALOG = "catalog.txt"
MOVEMENTS = "movements.txt"
ORDERS = "orders.txt"

# command -> (allowed positional counts, takes --json, takes --format)
JSON_COMMANDS = {"stock": (0,), "low": (0,), "history": (1,), "quote": (1,), "invoice": (1,)}
PLAIN_COMMANDS = {"receive": (3, 4), "ship": (3, 4), "fulfil": (2,)}
FORMATS = ("text", "csv", "json")


class Exit(Exception):
    """Stop with a message on stderr and an exit status."""

    def __init__(self, status: int, message: str):
        super().__init__(message)
        self.status = status
        self.message = message


def usage_error(message: str) -> Exit:
    return Exit(2, f"{message}\n{USAGE}".rstrip("\n"))


class Args:
    def __init__(self):
        self.command: Optional[str] = None
        self.dir = "."
        self.json = False
        self.format = "text"
        self.positionals: List[str] = []


def parse_args(argv: List[str]) -> Args:
    args = Args()
    rest: List[str] = []
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--dir":
            if i + 1 >= len(argv):
                raise usage_error("option --dir needs a value")
            args.dir = argv[i + 1]
            i += 2
            continue
        if arg.startswith("--dir="):
            args.dir = arg[len("--dir="):]
        else:
            rest.append(arg)
        i += 1

    position = next((n for n, a in enumerate(rest) if not a.startswith("-")), None)
    if position is None:
        raise usage_error("no command given")
    args.command = rest[position]
    before = rest[:position]
    after = rest[position + 1:]

    if args.command in PLAIN_COMMANDS:
        if before:
            raise usage_error(f"unknown option {before[0]}")
        args.positionals = after
        counts = PLAIN_COMMANDS[args.command]
    elif args.command in JSON_COMMANDS or args.command == "report":
        options = before + after
        j = 0
        while j < len(options):
            arg = options[j]
            if not arg.startswith("-"):
                args.positionals.append(arg)
            elif arg == "--json" and args.command in JSON_COMMANDS:
                args.json = True
            elif arg == "--format" and args.command == "report":
                if j + 1 >= len(options):
                    raise usage_error("option --format needs a value")
                args.format = options[j + 1]
                j += 1
            elif arg.startswith("--format=") and args.command == "report":
                args.format = arg[len("--format="):]
            else:
                raise usage_error(f"unknown option {arg}")
            j += 1
        if args.format not in FORMATS:
            raise usage_error(f"bad --format value {args.format!r} (use text, csv or json)")
        counts = JSON_COMMANDS.get(args.command, (0,))
    else:
        raise usage_error(f"unknown command {args.command!r}")

    if len(args.positionals) not in counts:
        raise usage_error(f"wrong number of arguments for {args.command}")

    date_index = {"receive": 0, "ship": 0, "fulfil": 1}.get(args.command)
    if date_index is not None and parse_date(args.positionals[date_index]) is None:
        raise usage_error(f"bad date {args.positionals[date_index]!r} (use YYYY-MM-DD)")
    return args


class Files:
    """Reads the data files from the folder, remembering raw bytes for appends."""

    def __init__(self, folder: str):
        if not os.path.isdir(folder):
            raise Exit(2, f"{folder}: no such directory")
        self.folder = folder

    def path(self, name: str) -> str:
        return os.path.join(self.folder, name)

    def read_bytes(self, name: str, required: bool) -> Optional[bytes]:
        try:
            with open(self.path(name), "rb") as handle:
                return handle.read()
        except FileNotFoundError:
            if required:
                raise Exit(2, f"{name}: file not found")
            return None
        except OSError as exc:
            raise Exit(2, f"{name}: cannot read: {exc.strerror or exc}")

    def read_text(self, name: str, required: bool = False) -> str:
        data = self.read_bytes(name, required)
        if data is None:
            return ""
        try:
            return data.decode("utf-8")
        except UnicodeDecodeError:
            raise Exit(2, f"{name}: not valid UTF-8")

    def append(self, name: str, text: str) -> None:
        path = self.path(name)
        existing = self.read_bytes(name, required=False)
        prefix = "\n" if existing and not existing.endswith(b"\n") else ""
        try:
            with open(path, "ab") as handle:
                handle.write((prefix + text).encode("utf-8"))
        except OSError as exc:
            raise Exit(2, f"{name}: cannot write: {exc.strerror or exc}")


def parsed(name: str, parser, *args):
    try:
        return parser(*args)
    except ParseError as exc:
        raise Exit(1, f"{name}: {exc}")


def to_json(value) -> str:
    return json.dumps(value, indent=2, ensure_ascii=False) + "\n"


def lines_out(lines: List[str]) -> str:
    return "".join(line + "\n" for line in lines)


# ---------------------------------------------------------------- shelves


def cmd_stock(args: Args, catalog, movements) -> str:
    levels = shelves.stock_levels(catalog, movements)
    rows = []
    for sku in sorted(catalog):
        product = catalog[sku]
        rows.append({"sku": sku, "name": product.name, "onhand": levels[sku],
                     "status": shelves.status(levels[sku], product.reorder)})
    if args.json:
        return to_json(rows)
    return lines_out([f"{r['sku']} {r['onhand']} {r['status']} {r['name']}" for r in rows])


def cmd_low(args: Args, catalog, movements) -> str:
    levels = shelves.stock_levels(catalog, movements)
    rows = []
    for sku in sorted(catalog):
        product = catalog[sku]
        onhand = levels[sku]
        if shelves.status(onhand, product.reorder) in ("low", "out"):
            rows.append({"sku": sku, "onhand": onhand, "reorder": product.reorder,
                         "buy": shelves.buy_quantity(onhand, product.reorder)})
    if args.json:
        return to_json(rows)
    return lines_out([f"{r['sku']} {r['onhand']} {r['reorder']} {r['buy']}" for r in rows])


def known_sku(text: str, catalog) -> str:
    sku = parse_sku(text)
    if sku is None or sku not in catalog:
        raise Exit(1, f"unknown SKU {text!r}")
    return sku


def cmd_history(args: Args, catalog, movements) -> str:
    sku = known_sku(args.positionals[0], catalog)
    rows = [{"date": m.date.isoformat(), "delta": f"{m.quantity:+d}", "balance": balance, "note": m.note}
            for m, balance in shelves.history(sku, movements)]
    if args.json:
        return to_json(rows)
    out = []
    for r in rows:
        text = f"{r['date']} {r['delta']} {r['balance']}"
        out.append(f"{text} {r['note']}" if r["note"] else text)
    return lines_out(out)


def cmd_move(args: Args, files: Files, catalog, movements) -> str:
    date = parse_date(args.positionals[0])
    sku = known_sku(args.positionals[1], catalog)
    qty_text = args.positionals[2]
    if not WHOLE_RE.fullmatch(qty_text) or int(qty_text) == 0:
        raise Exit(1, f"bad quantity {qty_text!r} (a whole number of one or more, no sign)")
    note = args.positionals[3] if len(args.positionals) == 4 else ""
    if "\n" in note or "\r" in note:
        raise Exit(1, "a note may not contain a line break")
    try:
        note.encode("utf-8")
    except UnicodeEncodeError:
        raise Exit(1, "a note must be valid UTF-8")
    note = note.strip(SPACES)
    quantity = int(qty_text) if args.command == "receive" else -int(qty_text)
    move = Movement(date, sku, quantity, note)
    bad = first_below_zero(movements + [move])
    if bad is move:
        raise Exit(1, f"stock of {sku} would go below zero")
    if bad is not None:
        raise Exit(1, f"{MOVEMENTS}: line {bad.line}: stock of {sku} would go below zero")
    line = shelves.format_movement(move)
    files.append(MOVEMENTS, line + "\n")
    return line + "\n"


# ---------------------------------------------------------------- orders


def find_order(text: str, orders):
    order_id = parse_order_id(text)
    for order in orders:
        if order.id == order_id:
            return order
    raise Exit(1, f"unknown order {text!r}")


def quote_output(header: str, order, quote: Quote, as_json: bool) -> str:
    if as_json:
        return to_json({
            "order": order.id,
            "date": order.date.isoformat(),
            "customer": order.customer,
            "lines": [{"sku": l.sku, "quantity": l.quantity, "unit": fmt(l.unit), "gross": fmt(l.gross),
                       "discount": fmt(l.discount), "net": fmt(l.net)} for l in quote.lines],
            "subtotal": fmt(quote.subtotal),
            "order_discount": fmt(quote.order_discount),
            "tax": fmt(quote.tax),
            "total": fmt(quote.total),
        })
    out = [header]
    for l in quote.lines:
        out.append(f"{l.sku} {l.quantity} {fmt(l.unit)} {fmt(l.gross)} {fmt(l.discount)} {fmt(l.net)}")
    out.append(f"subtotal {fmt(quote.subtotal)}")
    out.append(f"order discount {fmt(quote.order_discount)}")
    out.append(f"tax {fmt(quote.tax)}")
    out.append(f"total {fmt(quote.total)}")
    return lines_out(out)


def order_header(order) -> str:
    return f"{order.id} {order.date.isoformat()} {order.customer}"


def cmd_quote(args: Args, catalog, orders) -> str:
    order = find_order(args.positionals[0], orders)
    return quote_output(order_header(order), order, price_order(order, catalog), args.json)


def cmd_invoice(args: Args, catalog, movements, orders) -> str:
    order = find_order(args.positionals[0], orders)
    quote = orders_mod.invoice_quote(order, catalog, movements)
    if quote is None:
        raise Exit(1, f"nothing has shipped yet for order {order.id}")
    return quote_output("invoice " + order_header(order), order, quote, args.json)


def cmd_fulfil(args: Args, files: Files, catalog, movements, orders) -> str:
    order = find_order(args.positionals[0], orders)
    date = parse_date(args.positionals[1])
    if date < order.date:
        raise Exit(1, f"date {date.isoformat()} is before the date of order {order.id} ({order.date.isoformat()})")
    shipped = orders_mod.shipped_so_far(order, movements)
    plan = orders_mod.fulfil_plan(order, date, movements)
    new_moves = [Movement(date, sku, -plan[sku], orders_mod.order_note(order))
                 for sku, _ in order.lines if plan[sku] > 0]
    out = []
    after: Dict[str, int] = {}
    for sku, quantity in order.lines:
        after[sku] = shipped[sku] + plan[sku]
        out.append(f"{sku} shipped {plan[sku]} backordered {quantity - after[sku]}")
    out.append(f"status {orders_mod.order_status(order, after)}")
    if new_moves:
        files.append(MOVEMENTS, lines_out([shelves.format_movement(m) for m in new_moves]))
    return lines_out(out)


def cmd_report(args: Args, catalog, movements, orders) -> str:
    rows = orders_mod.report_rows(orders, catalog, movements)
    for row in rows:
        row["quoted"] = fmt(row["quoted"])
        row["invoiced"] = fmt(row["invoiced"]) if row["invoiced"] is not None else "0.00"
    if args.format == "json":
        return to_json(rows)
    if args.format == "csv":
        buffer = io.StringIO()
        fields = ["order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced"]
        writer = csv.DictWriter(buffer, fieldnames=fields, lineterminator="\n")
        writer.writeheader()
        writer.writerows(rows)
        return buffer.getvalue()
    return lines_out([f"{r['order']} {r['date']} {r['customer']} {r['status']} "
                      f"{r['shipped']}/{r['ordered']} {r['quoted']} {r['invoiced']}" for r in rows])


# ---------------------------------------------------------------- main


def run(argv: List[str]) -> str:
    args = parse_args(argv)
    files = Files(args.dir)
    command = args.command
    catalog = parsed(CATALOG, parse_catalog, files.read_text(CATALOG, required=True))
    movements = orders = None
    if command != "quote":
        movements = parsed(MOVEMENTS, parse_movements, files.read_text(MOVEMENTS), catalog)
    if command in ("quote", "fulfil", "invoice", "report"):
        orders = parsed(ORDERS, parse_orders, files.read_text(ORDERS), catalog)

    if command == "stock":
        return cmd_stock(args, catalog, movements)
    if command == "low":
        return cmd_low(args, catalog, movements)
    if command == "history":
        return cmd_history(args, catalog, movements)
    if command in ("receive", "ship"):
        return cmd_move(args, files, catalog, movements)
    if command == "quote":
        return cmd_quote(args, catalog, orders)
    if command == "fulfil":
        return cmd_fulfil(args, files, catalog, movements, orders)
    if command == "invoice":
        return cmd_invoice(args, catalog, movements, orders)
    return cmd_report(args, catalog, movements, orders)


def write_stderr(text: str) -> None:
    try:
        sys.stderr.buffer.write(text.encode("utf-8", "replace"))
        sys.stderr.flush()
    except (OSError, AttributeError, ValueError):
        pass


def main(argv: Optional[List[str]] = None) -> int:
    if argv is None:
        argv = sys.argv[1:]
    try:
        output = run(list(argv))
    except Exit as exc:
        write_stderr(f"stockroom: {exc.message}\n")
        return exc.status
    stdout = sys.stdout
    if stdout is None:
        write_stderr("stockroom: cannot write output: standard output is closed\n")
        return 1
    try:
        stdout.buffer.write(output.encode("utf-8"))
        stdout.flush()
    except BrokenPipeError:
        discard_stdout(stdout)
        return 0
    except (OSError, ValueError, AttributeError) as exc:
        discard_stdout(stdout)
        reason = exc.strerror if isinstance(exc, OSError) and exc.strerror else str(exc)
        write_stderr(f"stockroom: cannot write output: {reason}\n")
        return 1
    return 0


def discard_stdout(stdout) -> None:
    """Point stdout at the null device so the final flush at exit cannot fail again."""
    try:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, stdout.fileno())
        os.close(devnull)
    except (OSError, ValueError, AttributeError):
        pass
