USAGE = """usage: stockroom [--dir DIR] COMMAND ...
commands:
  stock [--json]
  low [--json]
  history SKU [--json]
  receive DATE SKU QUANTITY [NOTE]
  ship DATE SKU QUANTITY [NOTE]
  quote ORDER [--json]
  fulfil ORDER DATE
  invoice ORDER [--json]
  report [--format text|csv|json]
"""

CATALOG = "catalog.txt"
MOVEMENTS = "movements.txt"
ORDERS = "orders.txt"

# command -> (allowed positional counts, takes --json, takes --format)
JSON_COMMANDS = {"stock": (0,), "low": (0,), "history": (1,), "quote": (1,), "invoice": (1,)}
PLAIN_COMMANDS = {"receive": (3, 4), "ship": (3, 4), "fulfil": (2,)}
FORMATS = ("text", "csv", "json")


class Exit(Exception):
    """Stop with a message on stderr and an exit status."""

    def __init__(self, status: int, message: str):
        super().__init__(message)
        self.status = status
        self.message = message


def usage_error(message: str) -> Exit:
    return Exit(2, f"{message}\n{USAGE}".rstrip("\n"))


class Args:
    def __init__(self):
        self.command: Optional[str] = None
        self.dir = "."
        self.json = False
        self.format = "text"
        self.positionals: List[str] = []


def parse_args(argv: List[str]) -> Args:
    args = Args()
    rest: List[str] = []
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--dir":
            if i + 1 >= len(argv):
                raise usage_error("option --dir needs a value")
            args.dir = argv[i + 1]
            i += 2
            continue
        if arg.startswith("--dir="):
            args.dir = arg[len("--dir="):]
        else:
            rest.append(arg)
        i += 1

    position = next((n for n, a in enumerate(rest) if not a.startswith("-")), None)
    if position is None:
        raise usage_error("no command given")
    args.command = rest[position]
    before = rest[:position]
    after = rest[position + 1:]

    if args.command in PLAIN_COMMANDS:
        if before:
            raise usage_error(f"unknown option {before[0]}")
        args.positionals = after
        counts = PLAIN_COMMANDS[args.command]
    elif args.command in JSON_COMMANDS or args.command == "report":
        options = before + after
        j = 0
        while j < len(options):
            arg = options[j]
            if not arg.startswith("-"):
                args.positionals.append(arg)
            elif arg == "--json" and args.command in JSON_COMMANDS:
                args.json = True
            elif arg == "--format" and args.command == "report":
                if j + 1 >= len(options):
                    raise usage_error("option --format needs a value")
                args.format = options[j + 1]
                j += 1
            elif arg.startswith("--format=") and args.command == "report":
                args.format = arg[len("--format="):]
            else:
                raise usage_error(f"unknown option {arg}")
            j += 1
        if args.format not in FORMATS:
            raise usage_error(f"bad --format value {args.format!r} (use text, csv or json)")
        counts = JSON_COMMANDS.get(args.command, (0,))
    else:
        raise usage_error(f"unknown command {args.command!r}")

    if len(args.positionals) not in counts:
        raise usage_error(f"wrong number of arguments for {args.command}")

    date_index = {"receive": 0, "ship": 0, "fulfil": 1}.get(args.command)
    if date_index is not None and parse_date(args.positionals[date_index]) is None:
        raise usage_error(f"bad date {args.positionals[date_index]!r} (use YYYY-MM-DD)")
